"""UniFi firewall policies a NetBox change moves."""

import ipaddress

HEADER = (
    "# GENERATED by 'homelab generate' from NetBox. Do not hand-edit.\n"
    "# Re-run it after changing NetBox; `--check` reports drift.\n"
)


def cross_site_ipv6(site: dict, sites: dict) -> list[tuple[str, list[tuple[str, str]]]]:
    """Site Magic carries IPv4 alone, so another site's IPv6 is reached over the internet,
    where it answers only what it serves the internet. Rejecting the rest sends Happy Eyeballs
    to IPv4, over Site Magic, at once. Each policy in order, with its destinations and whose."""
    others = [s for s in sites.values() if s["slug"] != site["slug"] and s["gua_prefix"]]
    allow = [(p, s["slug"]) for s in others for p in s["internet_facing"] if ipaddress.ip_network(p).version == 6]
    reject = [(s["gua_prefix"], s["slug"]) for s in others]
    return [(action, to) for action, to in (("Allow", allow), ("Reject", reject)) if to]


def cross_site_ipv6_text(site: dict, sites: dict) -> str | None:
    policies = cross_site_ipv6(site, sites)
    if not policies:
        return None
    width = max(len(p) for _, to in policies for p, _ in to)
    lines = [
        HEADER,
        f"# From each of {site['slug']}'s zones to External, IPv6, any protocol and port, in this order.",
    ]
    for n, (action, to) in enumerate(policies, start=1):
        lines += ["", f"{n}. {action}"]
        lines += [f"   {p:<{width}}  {slug}" for p, slug in to]
    return "\n".join(lines) + "\n"
